import itertools

def is_colorful(m, n, w):
    # n: number of flavors (1 to n)
    # w: window size
    # m: total candies
    # Try all possible sequences of flavors
    for seq in itertools.product(range(1, n + 1), repeat=m):
        possible = True
        for i in range(m):
            window = set()
            for j in range(w):
                window.add(seq[(i + j) % m])
            if len(window) < n:
                possible = False
                break
        if possible:
            return True
    return False

# Test for small n, w
# n=2, w=3
for m in range(3, 11):
    print(f"m={m}, colorful={is_colorful(m, 2, 3)}")

def is_colorful_fast(m, n, w):
    # n: number of flavors (1 to n)
    # w: window size
    # m: total candies
    # Use backtracking to find if any sequence works
    seq = [0] * m
    def backtrack(idx):
        if idx == m:
            # Check all windows
            for i in range(m):
                window = set()
                for j in range(w):
                    window.add(seq[(i + j) % m])
                if len(window) < n:
                    return False
            return True

        for flavor in range(1, n + 1):
            seq[idx] = flavor
            # Partial check: a window that's fully filled can be checked
            # But since it's a circle, it's easier to check everything at the end
            # For small m, this is okay.
            if backtrack(idx + 1):
                return True
        return False

    return backtrack(0)

