def check_m_robust(m, n, w):
    import itertools

    def is_valid(seq):
        for i in range(m):
            window = set()
            for j in range(w):
                window.add(seq[(i + j) % m])
            if len(window) < n:
                return False
        return True

    # For small m, we can use itertools.product
    # But for larger m, we need backtracking.
    seq = [0] * m
    def backtrack(idx):
        if idx == m:
            return is_valid(seq)

        for flavor in range(1, n + 1):
            seq[idx] = flavor
            # Pruning: any window that is now complete must have size <= n.
            # A window [i, i+w-1] is complete if i+w-1 <= idx.
            # Since we're checking for all i, we only check i such that i+w-1 = idx.
            # This window is seq[idx-w+1 : idx+1].
            if idx >= w - 1:
                window = set(seq[idx-w+1 : idx+1])
                if len(window) > n:
                    continue

            if backtrack(idx + 1):
                return True
        return False
    return backtrack(0)

